style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
body, html {
    background: url("https://i.imgur.com/RqgDIuo.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  * {
    color: #ffffff !important;
  }

  a, a:link, a:visited {
    color: #ffbfe3 !important;
  }

  a:hover, a:active {
    color: #ffc8eb !important;
  }

  .icon, .menu-icon, [class*="icon-"], [class*="menu-icon"] {
    color: #ffffff !important;
    fill: #ffffff !important;
  }
}
